head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[util > M > getChildNodeAt]<br/>주어진 DOM 요소의 Element 자식 노드 중 지정한 인덱스 위치의 노드를 반환합니다.",
    "validation" : [
        "info(필수) 파라미터로 자식을 검색할 DOM 요소를 설정할 수 있어야 합니다.",
        "index(필수) 파라미터로 반환할 자식 Element 의 인덱스값을 설정할 수 있어야 합니다.",
        "인덱스는 0 부터 시작하며 해당 인덱스의 Element 자식 노드를 반환해야 합니다.",
        "텍스트 노드는 건너뛰어야 합니다.",
        "인덱스가 Element 자식 수를 초과하면 null 을 반환해야 합니다.",
    ]
}



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof grp_test !== 'undefined') {
        grp_test.remove();
    }

    let ns = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    // grp_test: 텍스트 노드 + 자식 3개를 가진 그룹
    let strGrpTest = '<xf:group ' + ns + ' style=""></xf:group>';
    scwin.grp_test = await $p.dynamicCreate('grp_test', 'group', strGrpTest, grp_comp);

    // 첫 번째 자식 앞에 텍스트 노드 삽입 (텍스트 노드 건너뛰기 검증용)
    let grpTestEl = document.querySelector("div[id*='grp_test']");
    let textNode = document.createTextNode("텍스트 노드");
    grpTestEl.insertBefore(textNode, grpTestEl.firstChild);

    let strChild1 = '<w2:textbox ' + ns + ' label="첫번째" style=""></w2:textbox>';
    await $p.dynamicCreate('txt_child1', 'textbox', strChild1, scwin.grp_test);

    let strChild2 = '<w2:textbox ' + ns + ' label="두번째" style=""></w2:textbox>';
    await $p.dynamicCreate('txt_child2', 'textbox', strChild2, scwin.grp_test);

    let strChild3 = '<w2:textbox ' + ns + ' label="세번째" style=""></w2:textbox>';
    await $p.dynamicCreate('txt_child3', 'textbox', strChild3, scwin.grp_test);
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 동적 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.btn_getChildNodeAt_onclick = function () {
    let index = Number(par_index.getValue());

    let element = document.querySelector("div[id*='grp_test']");
    let ret = WebSquare.util.getChildNodeAt(element, index);

    let result = [];
    result.push("index: " + index);

    if (ret) {
        result.push("tagName: " + ret.tagName);
        result.push("nodeType: " + ret.nodeType);
        result.push("id: " + (ret.id || '(없음)'));
    } else {
        result.push("반환값: null");
    }

    wf_body_bottom.getObj("scwin").setReturnValue(result.join(", "));
}
